package com.acme.core.common.security;

import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;

/**
 * Password hashing baseline (generated by engineering-platform 0.1.0).
 * BCrypt only — never plaintext. Uses spring-security-crypto (BCrypt utility only,
 * no Spring Security framework).
 */
public final class PasswordEncoder {

    private static final BCryptPasswordEncoder ENCODER = new BCryptPasswordEncoder();

    private PasswordEncoder() {
    }

    public static String hash(String rawPassword) {
        return ENCODER.encode(rawPassword);
    }

    public static boolean verify(String rawPassword, String passwordHash) {
        if (rawPassword == null || passwordHash == null) {
            return false;
        }
        return ENCODER.matches(rawPassword, passwordHash);
    }
}
